import sys
import math

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        a = int(next(it))
        b = int(next(it))
        delta = (b - a) / 500.0
        prob = 0.0
        # x_i = a + i * delta, i = 0..499
        for i in range(500):
            x = a + i * delta
            prob += math.sin(math.sqrt(x)) / 5.68 * delta
        out_lines.append('1' if prob > 0.5 else '0')
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()
```

